from itertools import product
from collections import Counter
Aopts = ['KNR','MNP','LMQ','LNR','MNR']
Bopts = ['KLN','NPR','PQR','KMP','LPQ']
Adays = [{2,6},{1,4,7},{6,7},{3,5},{1,6}]
Bdays = [{4,7},{2},{3,7},{4,5},{3,5,8}]
As = [a for a in product(*Aopts) if len(set(a)) == 5]
Bs = [b for b in product(*Bopts) if len(set(b)) == 5]
hist = Counter()
witness = {}
for a in As:
    for b in Bs:
        common = set(a) & set(b)
        if len(common) != 3 or len(common & set('KQR')) != 1:
            continue
        days = {p:set() for p in 'KLMNPQR'}
        for p,d in zip(a,Adays): days[p].update(d)
        for p,d in zip(b,Bdays): days[p].update(d)
        count = sum(len(d)>=3 for d in days.values())
        hist[count] += 1
        witness.setdefault(count, {'A': ''.join(a), 'B': ''.join(b)})
print({'feasible_linkages':sum(hist.values()), 'histogram':dict(sorted(hist.items())), 'bounds':[min(hist), max(hist)], 'low_witness':witness[min(hist)], 'high_witness':witness[max(hist)]})

